+++ b/apps/birdseye/internal/registry/cache.go
@@ -0,0 +1,49 @@
+// Package registry talks to a Crow server through its typed client and
+// caches module tarballs on disk so repeated diffs against the same
+// versions stay fast.
+package registry
+
+import (
+	"sync"
+
+	"github.com/immuta/operations/services/crow/pkg/api"
+)
+
+// Cache is the storage seam used by Registry. Production uses DiskCache;
+// tests inject MemCache.
+type Cache interface {
+	Get(api.Module) ([]byte, bool, error)
+	Put(api.Module, []byte) error
+}
+
+// MemCache is a thread-safe in-memory Cache implementation.
+type MemCache struct {
+	mu    sync.RWMutex
+	items map[string][]byte
+}
+
+// NewMemCache returns an empty MemCache.
+func NewMemCache() *MemCache {
+	return &MemCache{items: make(map[string][]byte)}
+}
+
+func memKey(m api.Module) string {
+	return m.Namespace + "/" + m.Name + "/" + m.Provider + "/" + m.Version
+}
+
+func (c *MemCache) Get(m api.Module) ([]byte, bool, error) {
+	c.mu.RLock()
+	defer c.mu.RUnlock()
+	b, ok := c.items[memKey(m)]
+	if !ok {
+		return nil, false, nil
+	}
+	return b, true, nil
+}
+
+func (c *MemCache) Put(m api.Module, body []byte) error {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	c.items[memKey(m)] = body
+	return nil
+}
