+++ b/apps/birdseye/internal/registry/cache_test.go
@@ -0,0 +1,31 @@
+package registry
+
+import (
+	"testing"
+
+	"github.com/immuta/operations/services/crow/pkg/api"
+)
+
+func mod(version string) api.Module {
+	return api.Module{
+		ModuleIdentifier: api.ModuleIdentifier{Namespace: "iac", Name: "comply", Provider: "aws"},
+		Version:          version,
+	}
+}
+
+func TestMemCacheRoundTrip(t *testing.T) {
+	c := NewMemCache()
+	if _, ok, err := c.Get(mod("1.0.0")); err != nil || ok {
+		t.Fatalf("expected miss; got ok=%v err=%v", ok, err)
+	}
+	if err := c.Put(mod("1.0.0"), []byte("payload")); err != nil {
+		t.Fatalf("Put: %v", err)
+	}
+	got, ok, err := c.Get(mod("1.0.0"))
+	if err != nil || !ok {
+		t.Fatalf("expected hit; got ok=%v err=%v", ok, err)
+	}
+	if string(got) != "payload" {
+		t.Errorf("body = %q", got)
+	}
+}
